using UnityEditor;
using UnityEngine;

/// <summary>
/// Import settings for assets generated by art/blender/generate_assets.py.
/// Models carry no materials of their own (the game uses one shared palette material),
/// and the palette texture must stay crisp so each face keeps its exact colour.
/// </summary>
public sealed class AssetImportRules : AssetPostprocessor
{
    private void OnPreprocessModel()
    {
        if (!assetPath.StartsWith("Assets/Models/")) return;

        var importer = (ModelImporter)assetImporter;
        importer.materialImportMode = ModelImporterMaterialImportMode.None;
        importer.importCameras = false;
        importer.importLights = false;
        importer.importBlendShapes = false;
        importer.animationType = ModelImporterAnimationType.None;
        importer.addCollider = false;
        importer.isReadable = false;
    }

    private void OnPreprocessTexture()
    {
        if (!assetPath.StartsWith("Assets/Textures/palette")) return;

        var importer = (TextureImporter)assetImporter;
        importer.filterMode = FilterMode.Point;
        importer.mipmapEnabled = false;
        importer.wrapMode = TextureWrapMode.Clamp;
        importer.textureCompression = TextureImporterCompression.Uncompressed;
        importer.sRGBTexture = true;
    }
}
